function Get-DocumentMap([string]$text) {
  $matches = [regex]::Matches($text, '(?m)^# FILE: `([^`]+)`\r?$')
  $documents = @{}
  for ($i = 0; $i -lt $matches.Count; $i++) {
    $match = $matches[$i]
    $end = if ($i + 1 -lt $matches.Count) { $matches[$i + 1].Index } else { $text.Length }
    $documents[$match.Groups[1].Value] = $text.Substring($match.Index, $end - $match.Index).TrimEnd()
  }
  return $documents
}

function Get-HeadingSection([string]$text, [string]$heading) {
  $match = [regex]::Match($text, '(?m)^' + [regex]::Escape($heading) + '\r?$')
  if (-not $match.Success) { throw "Required source heading not found: $heading" }
  $level = ([regex]::Match($heading, '^#+')).Length
  $tailStart = $match.Index + $match.Length
  $next = [regex]::Match($text.Substring($tailStart), "(?m)^#{1,$level} [^`r`n]+")
  $end = if ($next.Success) { $tailStart + $next.Index } else { $text.Length }
  return $text.Substring($match.Index, $end - $match.Index).TrimEnd()
}

