$workers = $workerJson | ConvertFrom-Json
foreach ($worker in $workers) {
  $out = @("# Specialist $($worker.id): $($worker.name)", "", "Codex task: $($worker.thread)", "Branch: $($worker.branch)", "Last known branch head: $($worker.head)", "", "## Shared sources", "Read the complete `docs/requirements/HEY_SHARED_FOUNDATION.md` and `docs/requirements/HEY_SOURCE_C_RECOVERY_DIRECTIVE.md`. Source A is the original detailed product specification. Source C later refines it and prevails on conflicts. Source B's relevant full subsystem prompts follow. All work applies to the existing HEY repository, not a separate package.", "", "## Scoped implementation assignment", $worker.task, "", "## Current code facts to validate", $worker.known, "", "## Source A: complete task-specific requirements")
  foreach ($name in $worker.files) { if (-not $documents.ContainsKey($name)) { throw "Missing Source A document $name for worker $($worker.id)" }; $out += "### Complete Source A document: ``$name``"; $out += $documents[$name]; $out += "" }
  foreach ($section in $worker.sections) { $file = $section[0]; $heading = $section[1]; $slice = Get-HeadingSection $documents[$file] $heading; $out += "### Complete Source A subsection: ``$heading`` (``$file``)"; $out += $slice; $out += "" }
  $out += @("## Source B: complete applicable Master Build Program prompts", "Apply each exact step prompt to the real repository with Source A/C precedence; do not produce standalone HEY-NEXT packages.", "")
  foreach ($step in $worker.steps) { if (-not $prompts.ContainsKey($step)) { throw "Missing Source B prompt $step for worker $($worker.id)" }; $out += $prompts[$step]; $out += "" }
  $out += @("## Source C: complete applicable approved refinements", "The complete newer directive is in the shared Source C file. The directly applicable sections are copied below verbatim.", "")
  foreach ($heading in $worker.c) { $out += (Get-HeadingSection $c $heading); $out += "" }
  $out += @("## Implementation and proof requirements", "Work only in your existing assigned checkout/branch. Inspect only your present implementation and preserve stronger work. Implement and wire the complete real user journey in scope; attack authorization, privacy, recovery and failure boundaries. Unit or stubbed tests are contract evidence only. Do not send secrets or claim external/native/provider behavior that was not actually exercised. Commit source changes, preserve handoff, and report exact SHA, tests, live entrypoint/output, frontend/backend/device integration evidence, unresolved blockers and next actions.", "")
  $path = Join-Path $specDir "HEY_SPECIALIST_$($worker.id)_BRIEF.md"
  # Preserve every source word while normalizing Markdown hard-break spaces so
  # the generated handoff briefs pass Git whitespace checks cleanly.
  $brief = ($out -join "`n") -replace '(?m) {2,}$', '<br>'
  [IO.File]::WriteAllText($path, ($brief.TrimEnd() + "`n"), $utf8)
}

$readme = @(
  "# HEY requirements recovery index", "", "Source A index: `HEY_SOURCE_A_INDEX.md` (all embedded document headings, source lines and sizes).", "Source B index: `HEY_SOURCE_B_INDEX.md` (exact numbered prompts 03–47).", "Source C: `HEY_SOURCE_C_RECOVERY_DIRECTIVE.md` (complete newer coordinator directive).", "Shared foundation: `HEY_SHARED_FOUNDATION.md` (complete Source A architecture/security/execution foundation files).", "Specialist assignments: `specialists/HEY_SPECIALIST_01_BRIEF.md` through `_11_BRIEF.md`; each embeds complete relevant Source A sections/documents, complete relevant Source B prompts, applicable verbatim Source C decisions and current code facts.", "", "Source A is 8,429,711 characters (SHA-256 `E617DFE4CA2E9C1DD753B53D3002C9E694BBB1582728D1AEF725D92F11E2B82D`); Source B is 932,280 characters (SHA-256 `3C48112DF44CB77ED97E04787097F34D376AB05E5ECD99C59DDB6B7DB3AAE401`); Source C is 27,949 characters (SHA-256 `77E11123BE403B0881AAD527D781973842DAE712710339429DBA619DB3496617`). The separate historical 4,210-item ledger is not attached and Source C explicitly says it is not HEY's feature target.", "")
[IO.File]::WriteAllText((Join-Path $base "README.md"), (($readme -join "`n").TrimEnd() + "`n"), $utf8)
Get-ChildItem -LiteralPath $base -File -Recurse | Select-Object Name,Length | Format-Table -AutoSize
